figure_legend_sections <- function() {
  supplied <- readLines('output/manuscript/legends-fig1-2.md',warn=FALSE)
  supplied <- gsub('grey text','gray text',supplied,fixed=TRUE)
  supplied <- supplied[!startsWith(supplied,'# ') & !startsWith(supplied,'The independent verifier checks archive structure') & !startsWith(supplied,'For the version without')]
  supplied <- gsub('{{eTable:avatar-trace}}','the AVATAR complete trace in the supplement',supplied,fixed=TRUE)
  domains <- 'D1, randomisation process; D2, deviations from intended interventions; D3, missing outcome data; D4, outcome measurement; D5, selection of the reported result.'
  coding <- 'Y, yes; PY, probably yes; N, no; PN, probably no; NI, no information. Five-level coding keeps all five answers; collapsed coding combines Y/PY and N/PN, with NI separate.'
  sections <- c(paste(supplied,collapse='\n'),
    'Figure 3 Paired evaluation and conditional primary endpoint. Both arms assessed the same 102 trials using the same Sonnet model and supplied documents. Two experts independently recorded ratings and signalling answers for all 510 trial-domain cells before viewing labels. In a separate stage, each chose among three labels presented in random order without rationales. The primary endpoint uses 60 agreed choices from 80 arm-discordant cells; 20 split choices enter sensitivities. The all-cell expert comparisons are not restricted to that conditional population. Counts are trials or cells as indicated; no interval applies.',
    paste('Figure 4 Absolute and paired domain agreement with each independent expert. Blue circles denote ARBITER and orange squares Unassisted. Left panels show exact agreement with 95% intervals on a 0–100% scale; right panels show paired ARBITER minus Unassisted differences in percentage points, with neutral diamonds and zero lines. Each expert contributes 510 pooled cells and 102 per domain. Expert-to-expert agreement is 388/510 (76.1%; weighted κ 0.59), context rather than a performance ceiling. The compact Published comparison retains all 510 cells. D1: randomisation process; D2: deviations from intended interventions; D3: missing outcome data; D4: outcome measurement; D5: selection of the reported result. Overall is supplementary.',CI_NOTE),
    paste('Figure 5 Paired signalling-answer diagnostics. Rows cover all five domains against each expert; n is the number of question components evaluable in both arms. Diamonds and bars show ARBITER minus Unassisted exact agreement and 95% intervals. Five-level matching distinguishes yes, probably yes, no, probably no and no information. Collapsed matching combines yes/probably yes and no/probably no, leaving no information separate. These are different estimands. D1: randomisation process; D2: deviations from intended interventions; D3: missing outcome data; D4: outcome measurement; D5: selection of the reported result. D3 and D5 illustrate reference dependence and the effect of coding; the complete question-level results, including sparse and unfavorable comparisons, are in eFigures 2 and 5. Source-specific absolute rates appear separately in eFigure 4.',CI_NOTE),
    paste('eFigure 1 Absolute agreement with independent experts by domain and derived Overall. ARBITER uses blue circles, Unassisted orange squares and Published dark-gray triangles, in that order. Short horizontal ticks show expert-to-expert agreement. Each domain has 102 cells; Overall uses 102 trials for the arms and expert reliability, and 81 for Published. Missing published Overall labels are excluded. Derived Overall against experts is exploratory. Bars show 95% percentile intervals. ',domains,CI_NOTE),
    paste('eFigure 2 Collapsed signalling-question paired differences. Rows identify the question, expert and paired denominator; only rows with at least 20 evaluable paired answers are shown. Dark circles show ARBITER − Unassisted differences with 95% percentile intervals. The complete sparse and five-level results appear in eFigure 5. ',domains,coding,CI_NOTE),
    paste('eFigure 3 Published-label agreement by source review. ARBITER uses blue circles and Unassisted orange squares. All 16 reviews remain visible; undefined κ is marked explicitly. Marks show linearly weighted κ with 95% percentile intervals, resampling the trials within reviews. ',CI_NOTE),
    paste('eFigure 4 Domain-level signalling agreement with each independent expert. ARBITER uses blue circles and Unassisted orange squares. Facets separate experts and five-level or collapsed answers; only evaluable source-specific answers contribute. Bars show 95% percentile intervals. Numerators and source/expert/domain-specific eligible denominators are in eTable 13, Full signalling question agreement, domain-summary rows. These denominators differ from the paired eligible intersections printed in eFigures 2 and 5. ',domains,coding,CI_NOTE),
    paste('eFigure 5 All signalling-question paired differences. Facets separate collapsed and five-level answers, including sparse and zero-answer rows. Dark circles show ARBITER − Unassisted differences with 95% percentile intervals; expert identity and paired n appear on each row. ',domains,coding,CI_NOTE))
  sub('^(e?Figure [0-9]+) ','\\1. ',sections)
}
build_figure_legends <- function() writeLines(enc2utf8(paste(figure_legend_sections(),collapse='\n\n')),'output/manuscript/figure-legends.md',useBytes=TRUE)

main_figure_alts <- function() c(
 'Architecture separating model interpretation from software source storage, evidence binding and executable RoB 2 decisions. The retained record supports reviewer inspection.',
 'Illustrative AVATAR assessment showing the result, domain judgments, signalling answers and linked source evidence. The example explains the workflow and is not a representative performance sample.',
 'Paired evaluation of 102 trials and 510 domain cells against two independent experts. A separate conditional branch contains 80 arm-discordant cells, 60 agreed choices and 20 splits.',
 'Exact agreement and paired gains against each expert, pooled and by domain. Both pooled gains favor ARBITER; D5 gains are largest and D3 depends strongly on the expert reference. The full-cohort Published comparison is shown separately.',
 'Paired signalling-answer differences by domain and expert, with five-level and collapsed coding separated. D3 changes direction with coding against Expert 1; D5 gains are smaller with collapsed coding against Expert 2.')
main_figure_captions <- function() {
  sections <- figure_legend_sections()
  text <- gsub('**','',sections[1],fixed=TRUE)
  pos <- regexpr('Figure 2',text,fixed=TRUE)[1]
  supplied <- c(trimws(substr(text,1,pos-1)),trimws(substr(text,pos,nchar(text))))
  supplied <- sub('Alt text:.*','',supplied)
  c(trimws(supplied),sections[2:4])
}
